unsigned process_audio_data(SF_PRIVATE* psf, unsigned len) {
    unsigned bytes_processed = 0;
    unsigned remaining = len;
    unsigned bytes_read;

    if (psf == NULL) {
        return 0;
    }

    if (len == 0) {
        return 0;
    }

    if (psf->decoder_state == FLAC__DECODER_ERROR) {
        return 0;
    }

    if (psf->buffer_pos > 0) {
        unsigned available = psf->buffer_len - psf->buffer_pos;
        unsigned to_copy = (available < remaining) ? available : remaining;
        memcpy(psf->output + bytes_processed, psf->buffer + psf->buffer_pos, to_copy);
        psf->buffer_pos += to_copy;
        bytes_processed += to_copy;
        remaining -= to_copy;
    }

    while (remaining > 0) {
        if (psf->decoder_state == FLAC__DECODER_ERROR) {
            return bytes_processed;
        }

        bytes_read = decode_next_block(psf, psf->output + bytes_processed, remaining);

        if (bytes_read == 0) {
            if (psf->decoder_state == FLAC__DECODER_STREAM_END) {
                psf->frame = NULL;
                return bytes_processed;
            }
            return bytes_processed;
        }

        bytes_processed += bytes_read;
        remaining -= bytes_read;
    }

    return bytes_processed;
}
